  "apr.mail.revoked": "{venue} has taken back your approval for {activity}. Their reason: {reason}\n\nYou cannot book it online, or get a door code for it, until you are approved again. The venue's staff look at any booking of it you already have, and will contact you.",
  "apr.mail.paymentLapsedSubject": "Your booking at {venue} was not paid in time",
