  "msg.voucherSubject": "Baucar hadiah anda untuk {venue}",
  "msg.voucher": "Hai {name}! Baucar hadiah {amount} anda untuk {venue} sudah sedia.\n\nKod: {code}\nSah sehingga {until}.\n\nCetak atau hantarkannya: {link}\n\nSesiapa yang memilikinya log masuk ke {site} dan memasukkan kod di halaman akaun mereka, dan ia menjadi kredit di {venue}.",
  "msg.reviewSubject": "Bagaimana {venue}?",
  "msg.review": "Hai {name}! Bagaimana {court} di {venue} pada {date}?\n\nNilai lawatan anda dalam beberapa saat: {link}\n\nUlasan anda membantu pemain lain memilih, dan tempat itu menambah baik. Ini satu-satunya kali {site} akan bertanya tentang {venue}.",
  "msg.mktConfirmSubject": "{venue}: sahkan anda mahu berita dan tawaran",
  "msg.mktConfirm": "Seseorang yang menempah di {venue} meminta berita dan tawaran dihantar ke alamat ini. Tiada apa-apa dihantar sehingga anda bersetuju: {link}\n\nJika bukan anda, abaikan e-mel ini dan tiada lagi yang akan dihantar.\n\n{site}",
  "msg.loyaltySubject": "{venue}: satu jam percuma untuk anda",
  "msg.loyalty": "Hai {name}, terima kasih kerana kerap bermain di {venue}. Setiap {every} jam yang anda mainkan di sini memberi anda satu jam percuma, dan anda telah mendapat satu.\n\nIa adalah pas {code}: tempah di {link} dan pilih untuk membayar dengan pas, atau tunjukkan di kaunter. Sah sehingga {until}.\n\n{site}",
  "msg.accountInvoiceSubject": "{venue}: invois {number} untuk {account}",
  "msg.accountInvoice": "Salam,\n\nIni invois {number} daripada {venue} untuk {account}: tempahan yang dicaj ke akaun anda, {total} kesemuanya, perlu dibayar sebelum {due}.\n\nLihat, cetak atau simpan sebagai PDF: {link}\n\n{site}",
  "msg.hireEnquirySubject": "{venue}: pertanyaan sewa persendirian daripada {name}",
  "msg.hireEnquiry": "{name} bertanya tentang sewa persendirian di {venue}.\n\nUntuk: {kind}\nTarikh: {date}\nBilangan orang: {people}\nTelefon: {phone}\nE-mel: {email}\n\n{message}\n\nJawab mereka, kemudian tandakannya di papan pemuka di bawah Tempahan.",
