  "su7.mail.new.s": "Lengkapkan pembukaan akaun {site} anda",
  "su7.mail.new.b": "Hai,\n\nSeseorang telah meminta untuk membuka akaun {site} dengan alamat e-mel ini. Jika itu anda, buka pautan ini dalam masa {minutes} minit untuk memilih nama, nombor telefon dan kata laluan anda:\n\n{link}\n\nPautan ini boleh digunakan sekali sahaja. Jika bukan anda, abaikan e-mel ini: tiada akaun dibuka.",
