  "su7.mail.existing.b": "Hai {name},\n\nSeseorang telah meminta untuk membuka akaun {site} dengan alamat e-mel ini. Anda sudah mempunyai akaun, jadi tiada akaun baharu dibuka dan tiada apa-apa pada akaun anda yang berubah.",
