  "err.R9_NOT_MEMBER": "Pusat ini untuk ahli sahaja, dan nombor ini tiada keahlian di sini dan tiada dalam senarai pusat. Tanya pusat cara menyertai.",
  "err.R9_NOT_LISTED": "Pusat ini persendirian, dan nombor ini tiada dalam senarainya. Minta pihak pengurusan menambahnya.",
  "err.R9_DESK_PHONE_BLOCKED": "Pusat telah menyekat nombor ini, jadi ia tidak boleh ditempah, walaupun oleh pengurus. Semak di Pusat & kakitangan → Nombor disekat, dan nyahsekat di sana, dengan sebabnya, jika sekatan itu patut dibuang.",
  "err.R9_DESK_UNPAID_VENUE": "Nombor ini sudah mempunyai {n} tempahan belum dibayar yang akan datang di sini. Terima bayaran untuk salah satu (tandakan sebagai dibayar) atau batalkan satu dahulu: had ini tidak boleh diatasi.",
