  "err.GC8_GUEST_OF_STAFF": "Hanya kakitangan pusat yang menempah seseorang sebagai tetamu ahli atau penghuni. Ahli dan penghuni menjemput tetamu mereka sendiri dari halaman akaun mereka.",
  "err.GC8_HOST_NOT_FOUND": "Nombor tuan rumah tiada dalam senarai pusat ini sebagai penghuni atau ahli bagi tarikh yang ditempah. Semak nombor itu, atau tambah tuan rumah ke senarai dahulu: ini tidak boleh diatasi.",
  "err.GC8_GUEST_IS_HOST": "Nombor tetamu ialah nombor tuan rumah sendiri. Tempah tuan rumah sebagai dirinya sendiri.",
