  "err.GC8_GUEST_ALLOWANCE": "Tuan rumah sudah mempunyai {n} tetamu dalam senarai, seramai yang dibenarkan pusat ini bagi setiap ahli atau penghuni pada satu masa. Keluarkan salah seorang tetamunya dari senarai dahulu, atau minta pengurus mengatasi had tetamu untuk tempahan ini jika pusat membenarkannya.",
