  "q8a.pay.notPaidHeld": "Tiada apa-apa yang ditolak. Tempahan anda disimpan untuk anda hanya sehingga masa di bawah semasa anda membayar dalam talian; jika tidak dibayar, ia dilepaskan untuk orang lain.",
  "q8a.pay.notPaidReleased": "Tiada apa-apa yang ditolak, dan tempahan itu telah dilepaskan kerana tidak dibayar tepat pada masanya.",
