  "q8a.claim.holdBefore": "Pusat ini meminta bayaran dalam talian: sebaik sahaja anda menuntutnya, tempahan disimpan selama {minutes} minit semasa anda membayar, dan dilepaskan jika tidak dibayar.",
  "q8a.claim.toVenue": "Kembali ke pusat",
