/** Exported so a test can hold the two languages against each other. */
export const DICTIONARIES: Record<Locale, Record<Phrase, string>> = { en: EN, ms: MS, zh: ZH, ta: TA };

export type Vars = Record<string, string | number>;

export function fill(text: string, vars?: Vars): string {
  if (!vars) return text;
  return text
    // An amount after the currency is written as money() writes it: 4.80, not 4.8.
    .replace(/\{cur\}\{(\w+)\}/g, (whole, name: string) =>
      "cur" in vars && typeof vars[name] === "number" ? `${vars.cur}${plainAmount(vars[name] as number)}` : whole
    )
    .replace(/\{(\w+)\}/g, (whole, name: string) => (name in vars ? String(vars[name]) : whole));
}

export interface T {
  (phrase: Phrase, vars?: Vars): string;
  /** The `_one` or `_other` form, with `{n}` already filled in. */
  plural(stem: string, n: number, vars?: Vars): string;
  locale: Locale;
  /** What this install calls itself. */
  site: string;
}

/**
 * The name of a refusal the customer can be shown.
 *
 * Derived from the dictionary rather than written out again: a code exists
 * exactly when there is something to say for it, in both languages, and
 * misspelling one in the store is a compile error rather than an English
 * sentence leaking into a Malay page.
 */
type ErrPhrase<P> = P extends `err.${infer C}` ? C : never;
type Stem<C> = C extends `${infer S}_one` ? S : C extends `${infer S}_other` ? S : C;
export type ErrorCode = Stem<ErrPhrase<Phrase>>;

/**
 * Filled into any phrase that names them: the site, the install's currency,
 * how a phone number is written there, the gateway venues pay through and how
 * customers pay with it, a place to search near, and the data law. The staff
 * dictionaries (lib/staff-i18n) are filled with the same.
 */
export function phraseVars(locale: Locale, site: string): Vars {
  const dict = DICTIONARIES[locale] ?? DICTIONARIES[DEFAULT_LOCALE];
  const r = region();
  return {
    site,
    cur: currencySymbol(),
    phoneEx: r.phone.example,
    gateway: GATEWAY_NAMES[r.gateway],
    payMethods: dict[`gw.${r.gateway}.methods` as Phrase] ?? "",
    placeEx: r.placeExample,
    tagline: r.tagline,
    dataAct: r.legal.dataAct,
  };
}

/** Whether the dictionary has this phrase at all. */
export function hasPhrase(key: string): key is Phrase {
  return key in DICTIONARIES.en;
}

/** The lookup for one language. */
/**
 * The lookup for one language. `{site}` in any phrase is the install's name:
 * on the server that comes from SITE_NAME; in the browser, from the server,
 * through the language provider.
 */
export function translator(locale: Locale, site: string = siteName()): T {
  const dict = DICTIONARIES[locale] ?? DICTIONARIES[DEFAULT_LOCALE];
  const base = phraseVars(locale, site);
  const t = ((phrase: Phrase, vars?: Vars) =>
    fill(dict[phrase] ?? String(phrase), { ...base, ...vars })) as T;
  t.plural = (stem: string, n: number, vars?: Vars) =>
    fill(dict[`${stem}_${n === 1 ? "one" : "other"}` as Phrase] ?? stem, { ...base, n, ...vars });
  t.locale = locale;
  t.site = site;
  return t;
}

/** What this language calls a sport. The icons are the same either way. */
/** An activity's name in the page's language, as this country calls it (the catalogue, lib/activity-registry.ts). */
export function sportLabel(t: T, sport: string): string {
  return activityName(sport, t.locale);
}

